const r = await api.get("/customers");
const list = Array.isArray(r) ? r : (r.items || r.customers || r.data || []);
console.log("type:", Array.isArray(r) ? "array" : Object.keys(r));
console.log("count:", list.length);
if (list.length) console.log("keys:", Object.keys(list[0]));

const r = await api.get("/customers");
const list = r.items;
const nov = list.filter(c => c.birth_date && String(c.birth_date).slice(5,7) === "11");
const formats = [...new Set(list.map(c => typeof c.birth_date === "string" ? c.birth_date.replace(/\d/g,"9") : typeof c.birth_date))];
console.log("returned:", list.length, "total count field:", r.count);
console.log("birth_date formats:", formats);
console.log("november birthdays:", nov.length);

